ns.holidays = {
    ["10v10 rated battlegrounds are available.  Join a group with 9 other players and queue for a rated battleground from the PvP menu to earn Conquest Points."] = "Доступні рейтингові поля бою 10 на 10. Приєднайтеся до групи з 9 іншими гравцями й станьте в чергу на рейтингове поле бою через меню PvP, щоб заробити Очки Завоювання.",
    ["15v15 rated battlegrounds are available.  Join a group with 14 other players and queue for a rated battleground from the PvP menu to earn Conquest Points."] = "Доступні рейтингові поля бою 15 на 15. Приєднайтеся до групи з 14 іншими гравцями й станьте в чергу на рейтингове поле бою через меню PvP, щоб заробити Очки Завоювання.",
    ["25v25 rated battlegrounds are available.  Join a group with 24 other players and queue for a rated battleground from the PvP menu to earn Conquest Points."] = "Доступні рейтингові поля бою 25 на 25. Приєднайтеся до групи з 24 іншими гравцями й станьте в чергу на рейтингове поле бою через меню PvP, щоб заробити Очки Завоювання.",
    ["7.3 Shadows of Argus: Week 1"] = "7.3 Тіні Аргуса: Тиждень 1",
